 Oswald;max-width:390px;line-height:1.1}.welcome{max-width:650px;margin:80px auto}.inline{display:inline}.config-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.config-item{display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--line);padding:10px 0}.config-form{display:flex;gap:8px}.config-form input{min-width:0;width:100%;border:1px solid #b9c7d2;border-radius:5px;padding:8px;font:inherit}@media(max-width:800px){.admin-grid{grid-template-columns:1fr}.stats,.config-grid,.form-grid{grid-template-columns:1fr}.login-wrap{grid-template-columns:1fr}.login-art{display:none}.shell{padding:16px}}
